<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue';
import { createPlay, type PlayScene, type Status } from './scene.ts';
import type { Feature, Study } from './model.ts';

const host = ref<HTMLDivElement>(), minimap = ref<HTMLCanvasElement>();
const study = ref<Study>(), status = ref<Status>(), error = ref(''), loading = ref(true), review = ref(false), details = ref(false), sprint = ref(false);
const selected = ref<Feature>(), request = ref(0);
let scene: PlayScene | undefined, disposed = false;
watch(review, value => { scene?.pause(value); if (!value) void nextTick(() => host.value?.querySelector('canvas')?.focus()); });
const pointString = (f: Feature) => f.points.map(p => `${p.x},${p.z}`).join(' ');
const mapBox = computed(() => study.value ? `${-study.value.halfSize} ${-study.value.halfSize} ${study.value.halfSize * 2} ${study.value.halfSize * 2}` : '0 0 1 1');
const walking = computed(() => !!status.value && !status.value.mode.startsWith('Exploration'));
const nearest = computed(() => study.value?.roads.slice().sort((a, b) => a.distanceM - b.distanceM).slice(0, 5) ?? []);
const control = (key: string, on: boolean) => scene?.key(key, on);
const clearSprint = () => { sprint.value = false; control('shift',false); };
const press = (e: PointerEvent, key: string) => { (e.currentTarget as HTMLElement).setPointerCapture(e.pointerId); control(key, true); };
function enter() { if (scene?.enter()) { sprint.value = false; scene.key('shift', false); } }
function explore() { scene?.explore(); sprint.value = false; }
function toggleSprint() { sprint.value = !sprint.value; control('shift', sprint.value); }
async function load(id: 'town' | 'fuw') {
  const generation = ++request.value;
  loading.value = true; error.value = ''; selected.value = undefined; sprint.value = false; status.value = undefined;
  scene?.dispose(); scene = undefined;
  try {
    const response = await fetch(`/${id}.json`);
    if (!response.ok) throw new Error(`Study unavailable (${response.status})`);
    const data = await response.json() as Study;
    if (disposed || generation !== request.value) return;
    study.value = data; await nextTick();
    if (!host.value || !minimap.value || disposed || generation !== request.value) return;
    scene = createPlay(host.value, data, minimap.value, value => { status.value = value; });
    // Town spawn was explicitly approved as simulation-only by the project owner.
    if (id === 'town') scene.enter();
    review.value = id === 'fuw';
  } catch (e) { if (!disposed && generation === request.value) error.value = e instanceof Error ? e.message : String(e); }
  finally { if (!disposed && generation === request.value) loading.value = false; }
}
onMounted(() => { window.addEventListener('blur',clearSprint); document.addEventListener('visibilitychange',clearSprint); void load('town'); });
onBeforeUnmount(() => { disposed = true; request.value++; window.removeEventListener('blur',clearSprint); document.removeEventListener('visibilitychange',clearSprint); scene?.dispose(); });
</script>

<template>
  <main>
    <header class="topbar">
      <a class="brand" href="/" aria-label="Wukari Life home"><span class="brand-icon">W<span>·</span></span><span>WUKARI <b>LIFE</b><small>GEOGRAPHIC GAMEPLAY PROTOTYPE</small></span></a>
      <nav aria-label="Study areas"><button :class="{active:study?.id==='town'}" @click="load('town')">Town demo</button><button :class="{active:study?.id==='fuw'}" @click="load('fuw')">FUW location review</button></nav>
      <span class="local"><i></i> LOCAL DEMONSTRATION</span>
    </header>
    <section class="workspace">
      <aside class="sidebar" :class="{open:details}">
        <p class="eyebrow">TARABA STATE · NIGERIA</p>
        <h1>Walk the map.<br><em>Know the limits.</em></h1>
        <p class="intro">A small, real slice of Wukari. Original road lines and building footprints, made explorable.</p>
        <div class="study-card" v-if="study"><span class="eyebrow">CURRENT STUDY</span><h2>{{ study.title }}</h2><div class="stats"><div><b>{{ study.coverage.roads }}</b><span>road ways</span></div><div><b>{{ study.coverage.buildings }}</b><span>footprints</span></div></div><p>{{ study.halfSize*2 }} m display window · {{ study.coverage.components }} road graph components</p></div>
        <div class="notice"><strong>Simulation, not real-world guidance</strong><p>Access, traffic and physical safety are unverified. Mapping does not grant permission to enter. This is not a completed FUW campus.</p></div>
        <p class="fine">Recorded positions are real OSM geometry. Flat ground, road widths and unmeasured building heights are illustrative. Movement stays in a narrow virtual road corridor.</p>
        <button class="source-button" @click="review=!review;details=false">{{ review?'Return to 3D view':'Map, sources & OSM IDs' }} <span>↗</span></button>
        <details class="credits"><summary>Sources & licences</summary><p>© <a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap contributors · ODbL 1.0</a>. Snapshot 19 Oct 2026. <a href="/README.md">Data offer & provenance</a>.</p><p>Code AGPL-3.0-or-later · <a href="https://github.com/Jabarteley/wukari-world">modified source</a> · based on Allworld.</p><p v-for="source in study?.sources" :key="source.url"><a :href="source.url" target="_blank" rel="noreferrer">{{ source.title }}</a></p></details>
      </aside>
      <section class="viewport" aria-label="Geographic prototype" :data-study="study?.id" :data-mode="status?.mode" :data-x="status?.position.x" :data-z="status?.position.z" :data-distance="status?.distance" :data-bearing="status?.bearing" :data-blocked="status?.blocked" :data-draws="status?.draws" :data-triangles="status?.triangles" :data-fps="status?.fps">
        <div ref="host" class="scene"></div>
        <div class="scene-heading"><span class="pill">{{ study?.id==='fuw'?'LOCATION EVIDENCE · NO CAMPUS BOUNDARY':'REAL OSM GEOMETRY · VIRTUAL TEST' }}</span><h2>{{ study?.id==='fuw'?'FUW candidate vicinity':'Wukari / Town road study' }}</h2></div>
        <div class="view-tools"><button @click="details=!details" aria-label="Study details" class="mobile-details">☰</button><button @click="review=!review" :aria-pressed="review">{{ review?'3D':'Map' }}</button><button @click="scene?.reset()" :disabled="!walking">Reset</button><button @click="walking?explore():enter()" :disabled="!walking&&!study?.spawn">{{ walking?'Explore':'Enter demo' }}</button></div>
        <aside class="minimap"><canvas ref="minimap" aria-label="North-up minimap of mapped roads and buildings"></canvas><span>N ↑ <b>{{ Math.round(status?.bearing??0) }}°</b></span></aside>
        <div v-if="loading" class="screen-message" role="status">Loading bounded source geometry…</div>
        <div v-if="error" class="screen-message" role="alert">{{ error }}<button @click="load('town')">Retry town study</button></div>
        <div class="hud" v-if="status&&!review"><div><i :class="{moving:status.speed>0}"></i><b>{{ status.mode }}</b><small>{{ status.distance.toFixed(1) }} m travelled · {{ status.speed.toFixed(1) }} m/s</small></div><span>{{ status.blocked?'Mapped building or virtual corridor limit':walking?'WASD / arrows · Shift sprint · drag or Q/E to look':'Drag to orbit · scroll to zoom' }}</span></div>
        <div class="touch-controls" v-if="walking&&!review" aria-label="Touch movement controls"><div class="dpad"><button class="up" aria-label="Move forward" @pointerdown.prevent="press($event,'w')" @pointerup="control('w',false)" @pointercancel="control('w',false)" @lostpointercapture="control('w',false)">↑</button><button class="left" aria-label="Move left" @pointerdown.prevent="press($event,'a')" @pointerup="control('a',false)" @pointercancel="control('a',false)" @lostpointercapture="control('a',false)">←</button><button class="down" aria-label="Move backward" @pointerdown.prevent="press($event,'s')" @pointerup="control('s',false)" @pointercancel="control('s',false)" @lostpointercapture="control('s',false)">↓</button><button class="right" aria-label="Move right" @pointerdown.prevent="press($event,'d')" @pointerup="control('d',false)" @pointercancel="control('d',false)" @lostpointercapture="control('d',false)">→</button></div><button class="sprint" :aria-pressed="sprint" @click="toggleSprint">{{ sprint?'Sprint ON':'Sprint' }}</button></div>
        <section class="review-panel" v-if="review&&study" aria-label="Reviewable geographic map">
          <div class="review-title"><div><span class="eyebrow">SOURCE REVIEW · NORTH UP</span><h2>{{ study.id==='fuw'?'FUW candidate location':'Town geographic study' }}</h2><p v-if="study.id==='fuw'">Research points support an approximate location. No campus boundary or building ownership is established.</p><p v-else>Source-centred display window. Public access remains unknown.</p></div><button @click="review=false" aria-label="Close geographic map">×</button></div>
          <div class="review-body"><svg :viewBox="mapBox" class="source-map" role="img" aria-label="OSM geometry and research candidate points"><rect :x="-study.halfSize" :y="-study.halfSize" :width="study.halfSize*2" :height="study.halfSize*2" fill="#ede7d7"/><polygon v-for="b in study.buildings" :key="`b${b.id}`" :points="pointString(b)" fill="#b49a7b" stroke="#8e785e" stroke-width=".5" class="map-feature" @click="selected=b"><title>OSM way/{{ b.id }} · nearby, ownership unverified</title></polygon><polyline v-for="r in study.roads" :key="`r${r.id}`" :points="pointString(r)" fill="none" stroke="#557c77" stroke-width="5" class="map-feature" @click="selected=r"><title>OSM way/{{ r.id }} · {{ r.tags.highway }}</title></polyline><g v-for="(p,i) in study.candidates" :key="p.label"><circle :cx="p.point.x" :cy="p.point.z" :r="i===0?10:7" fill="#e4863f" stroke="#fff" stroke-width="2"/><text :x="p.point.x+12" :y="p.point.z-12" font-size="18" fill="#233c39">{{ i===0?'Reported location':String.fromCharCode(64+i) }}</text></g><text :x="-study.halfSize+20" :y="-study.halfSize+32" font-size="22" fill="#23423e">N ↑</text><line :x1="-study.halfSize+25" :x2="-study.halfSize+125" :y1="study.halfSize-25" :y2="study.halfSize-25" stroke="#23423e" stroke-width="3"/><text :x="-study.halfSize+25" :y="study.halfSize-40" font-size="17">100 m display scale</text></svg>
            <div class="map-info"><p class="legend">● Orange: reported research positions<br>Green: original OSM road lines<br>Brown: original OSM footprints</p><div v-if="selected"><h3>OSM way/{{ selected.id }}</h3><p>{{ selected.distanceM.toFixed(1) }} m from study point (display projection)</p><pre>{{ JSON.stringify(selected.tags,null,2) }}</pre><p>Association: nearby only, FUW ownership unverified.</p><a :href="`https://www.openstreetmap.org/way/${selected.id}`" target="_blank" rel="noreferrer">View original OSM record ↗</a></div><div v-else><h3>Inspect a mapped feature</h3><p>Select a line or footprint to see its original ID, tags and distance.</p></div><h3>Nearby road records</h3><button v-for="r in nearest" :key="r.id" class="record" @click="selected=r"><span>way/{{ r.id }} <small>{{ r.tags.highway }}</small></span><b>{{ Math.round(r.distanceM) }} m</b></button><template v-if="study.id==='fuw'"><h3>Confidence & unknowns</h3><p>Moderate location confidence; 2018 sampling positions published in 2023, corroborated approximately in 2025. Datum and current accuracy unknown.</p><p>Wikidata’s unreferenced 7.8773°N, 9.779°E pin is about 3.8 km north. It is disputed, not used for the campus study.</p><p>Square frame is only a study window. No campus hull is inferred. Nearby geometry remains unassigned. Character spawning is disabled here.</p></template><p v-for="source in study.sources" :key="source.url" class="source"><a :href="source.url" target="_blank" rel="noreferrer">{{ source.title }}</a><small>{{ source.note }}</small></p></div></div>
        </section>
        <footer class="scene-footer"><span>© OpenStreetMap contributors · ODbL 1.0 · Unofficial community prototype</span><span v-if="status" class="telemetry">{{ status.draws }} draws · {{ Math.round(status.fps) }} fps</span></footer>
      </section>
    </section>
  </main>
</template>

<style>
